/** @jsxImportSource react */

import { cn } from '@videojs/utils/style';
import type { ComponentProps, ReactNode } from 'react';

import { StatusAnnouncer } from '../shared/components/behaviors/status-announcer';
import { Container } from '../shared/components/layout/container';
import { AudioErrorDialog } from '../shared/skins/shared/audio/dialogs/error-dialog';
import { PlaybackHotkeys } from '../shared/skins/shared/behaviors/playback-hotkeys';
import { DefaultAudioControls } from './layout/controls';

export interface AudioSkinProps extends Omit<NonNullable<ComponentProps<typeof Container>>, 'children'> {
  children?: ReactNode;
}

export function AudioSkin({ children, className, ...props }: AudioSkinProps = {}) {
  return (
    <Container className={cn('audio-skin', className)} data-theme="default" data-preset="audio" {...props}>
      {children}
      <AudioErrorDialog />
      <DefaultAudioControls />
      <PlaybackHotkeys />
      <StatusAnnouncer />
    </Container>
  );
}
